  if (!apiEnabled) {
    return fallbackData;
  }
  
  try {
    return await apiFunc();
  } catch (error) {
    console.warn('API call failed, using localStorage fallback:', error.message);
    apiEnabled = false; // Disable API after first failure
    return fallbackData;
  }
};

export const fetchTasks = async () => {
  // Get from localStorage first as backup
  const savedTasks = localStorage.getItem('melodicJustice_tasks');
  const localTasks = savedTasks ? JSON.parse(savedTasks) : [];
  
  return safeApiCall(async () => {
    const response = await axios.get(`${API_URL}/tasks`);
    return response.data;
  }, localTasks);
};

export const fetchNotes = async () => {
  // Get from localStorage first as backup
  const savedNotes = localStorage.getItem('melodicJustice_notes');
